const edition = globalThis.makeSubjectEdition({"subject":"chip","year":2020,"grade":"7-8","contest":"Человек и природа","letters":"АБВГД","count":30,"language":"ru","points":3,"tasksFile":"2020-2021_CHIP_Evrazia_zadanie_7-8-kl.pdf","answersFile":"reviewed-7-8.pdf","title":"Евразия","reviewedKey":true}, [{"title":"Моря у Европы","question":"Какое из этих морей не омывает берега европейской части Евразии?","choices":["Норвежское","Баренцево","Средиземное","Охотское","Северное"],"answer":3,"points":3,"steps":["Норвежское, Северное, Баренцево и Средиземное моря прилегают к европейским берегам.","Охотское море лежит у восточной окраины Азии между материком, Камчаткой и Курильскими островами."]},{"title":"Страна на карте Евразии","question":"Какая страна выделена на карте Евразии?","choices":["Китай","Казахстан","Турция","Монголия","Узбекистан"],"answer":1,"points":3,"steps":["Выделенная территория находится южнее России и простирается от Каспийского моря далеко в глубь материка.","Так расположен Казахстан. Монголия находится восточнее и не выходит к Каспийскому морю."],"figure":{"src":"assets/chip/2020/7-8-02.svg","alt":"Карта Евразии. Одна страна к югу от России выделена цветом.","width":408,"height":254,"detailSrc":"assets/chip/2020/7-8-02.svg"}},{"title":"Часовые зоны России","question":"Сколько официальных часовых зон было в России в год конкурса?","choices":["3","5","7","9","11"],"answer":4,"points":3,"steps":["Территория России очень вытянута с запада на восток. Поэтому время в Калининграде и на Камчатке сильно различается.","Первая из 11 зон соответствует UTC+2, крайняя восточная — UTC+12. Между ними десять часов разницы."],"adaptation":"Спрашивается число официальных часовых зон в 2020 году."},{"title":"Засушливый пояс Евразии","question":"Как называют экосистемы, показанные на фотографии? Они занимают большие площади в самых сухих районах Евразии, где растения покрывают лишь небольшую часть поверхности.","choices":["пустыни","степи","тундры","луга","маквис"],"answer":0,"points":3,"steps":["Вдали от морей в часть внутренних районов попадает очень мало влаги. На юго-западе материка также есть большие засушливые области, например Аравийская пустыня.","На снимке видны песчаные гряды почти без растительности. Это один из типов пустынных ландшафтов."],"figure":{"src":"assets/chip/2020/7-8-04.webp","alt":"Открытая засушливая область с песками, где растительность почти отсутствует.","width":384,"height":288,"detailSrc":"assets/chip/2020/detail/7-8-04.webp","pixelWidth":986,"pixelHeight":739}},{"title":"Люди моря на картине","question":"Кого Валентин Серов изобразил на этой картине?","choices":["казаки","поморы","бурлаки","кержаки","семейские"],"answer":1,"points":3,"steps":["Название «поморы» связано со словом «море». Так называют жителей Беломорского севера, традиционно промышлявших на море.","На картине люди работают среди лодок, мачт и снастей. Такой сюжет относится к быту поморов."],"figure":{"src":"assets/chip/2020/7-8-05.webp","alt":"Живописная сцена. Перед лодками и мачтами несколько людей в светлой одежде.","width":270,"height":384,"detailSrc":"assets/chip/2020/detail/7-8-05.webp","pixelWidth":1056,"pixelHeight":1500}},{"title":"Культура и охраняемый вид","question":"Какое из растений из Красной книги России выращивают как пищевую культуру в ряде районов Китая?","choices":["ковыль Залесского","лотос орехоносный","мускари длинноцветковый","клеоме донецкая","горечавка особенная"],"answer":1,"points":3,"steps":["В Китае у этого водного растения в пищу используют корневища и семена. Для выращивания подходят мелкие водоёмы.","В России лотос орехоносный встречается лишь в отдельных подходящих местах и охраняется."]},{"title":"Производство хлопка","question":"Какая из перечисленных стран собрала больше всего хлопка в год конкурса?","choices":["Пакистан","Туркменистан","Индия","Узбекистан","Турция"],"answer":2,"points":3,"steps":["Хлопчатник выращивают в нескольких странах из списка. Для сравнения важен общий объём сбора, который зависит и от площади посевов.","В сезоне около 2020 года Индия была одним из ведущих мировых производителей и опережала остальные страны списка."],"adaptation":"Рейтинг ограничен перечисленными странами и годом проведения конкурса."},{"title":"Созвездие южного неба","question":"Какое из показанных созвездий не восходит над горизонтом на 60° северной широты?","choices":["","","","",""],"answer":3,"points":3,"steps":["Южный Крест расположен далеко к югу от небесного экватора. С широты 60° северной широты его звёзды не поднимаются над горизонтом.","На схеме Г яркие точки образуют длинную ось креста и заметно более короткую поперечную."],"adaptation":"Указана широта: в некоторых тропических районах Северного полушария Южный Крест виден.","optionFigures":[{"src":"assets/chip/2020/7-8-08-1.svg","alt":"Группа звёзд образует большой многоугольник.","width":149,"height":142,"detailSrc":"assets/chip/2020/7-8-08-1.svg"},{"src":"assets/chip/2020/7-8-08-2.svg","alt":"У компактного четырёхугольника несколько точек продолжают одну сторону ломаной линией.","width":149,"height":142,"detailSrc":"assets/chip/2020/7-8-08-2.svg"},{"src":"assets/chip/2020/7-8-08-3.svg","alt":"На схеме открытая дуга из семи ярких точек.","width":149,"height":142,"detailSrc":"assets/chip/2020/7-8-08-3.svg"},{"src":"assets/chip/2020/7-8-08-4.svg","alt":"Две линии пересекаются под углом, возле длинной оси есть ещё одна звезда.","width":149,"height":142,"detailSrc":"assets/chip/2020/7-8-08-4.svg"},{"src":"assets/chip/2020/7-8-08-5.svg","alt":"Пять ярких точек соединены зигзагом.","width":149,"height":142,"detailSrc":"assets/chip/2020/7-8-08-5.svg"}]},{"title":"Обелиск «Центр Азии»","question":"В каком городе находится обелиск «Центр Азии» на фотографии?","choices":["Кызыле","Пекине","Новосибирске","Улан-Баторе","Лхасе"],"answer":0,"points":3,"steps":["Монумент расположен рядом с местом, где сливаются Большой и Малый Енисей. Этот район — в Республике Тыва.","Столица Тывы — Кызыл. В городе установили памятник географическому центру Азии."],"figure":{"src":"assets/chip/2020/7-8-09.webp","alt":"Длинный светлый шпиль над шаром на постаменте. За обелиском видны река и пологие горы.","width":288,"height":384,"detailSrc":"assets/chip/2020/detail/7-8-09.webp","pixelWidth":960,"pixelHeight":1280}},{"title":"Букет на подносе","question":"На какой фотографии изделие с жостовской росписью?","choices":["","","","",""],"answer":1,"points":3,"steps":["Жостовские мастера известны металлическими подносами с цветочными букетами. Тёмный фон подчёркивает яркие крупные цветы.","Такой цветочный букет на тёмном металлическом подносе виден под буквой Б."],"optionFigures":[{"src":"assets/chip/2020/5-6-14-1.webp","alt":"Деревянные изделия с многоцветными фигурами и сценками.","width":360,"height":232,"detailSrc":"assets/chip/2020/detail/5-6-14-1.webp","pixelWidth":1280,"pixelHeight":825},{"src":"assets/chip/2020/5-6-14-2.webp","alt":"На тёмном подносе крупный букет с красными и светлыми цветами.","width":360,"height":240,"detailSrc":"assets/chip/2020/detail/5-6-14-2.webp","pixelWidth":1280,"pixelHeight":853},{"src":"assets/chip/2020/5-6-14-3.webp","alt":"Светлая доска с рядами красно-чёрных геометрических узоров и фигурок животных.","width":250,"height":360,"detailSrc":"assets/chip/2020/detail/5-6-14-3.webp","pixelWidth":1111,"pixelHeight":1600},{"src":"assets/chip/2020/5-6-14-4.webp","alt":"Белый кувшин с крышкой, украшенный синей росписью.","width":270,"height":360,"detailSrc":"assets/chip/2020/detail/5-6-14-4.webp","pixelWidth":1200,"pixelHeight":1600},{"src":"assets/chip/2020/5-6-14-5.webp","alt":"Деревянная доска с красными ягодами и золотистыми листьями.","width":238,"height":360,"detailSrc":"assets/chip/2020/detail/5-6-14-5.webp","pixelWidth":1059,"pixelHeight":1600}],"adaptation":"На фотографиях показаны другие изделия тех же пяти промыслов. Порядок вариантов сохранён."},{"title":"Реки древнего Междуречья","question":"Между какими реками расположен исторический регион Междуречье, или Месопотамия?","choices":["Иртышом и Обью","Доном и Волгой","Амударьёй и Сырдарьёй","Тигром и Евфратом","Хуанхэ и Янцзы"],"answer":3,"points":4,"steps":["Месопотамия означает «земля между реками». Это название применяют к древней области на Ближнем Востоке.","Водоёмы, от которых зависело её земледелие, — Тигр и Евфрат."]},{"title":"Кого называют suslik","question":"Какого грызуна обозначает французское слово suslik, заимствованное из русского?","choices":["","","","",""],"answer":2,"points":4,"steps":["Французские написания souslik и suslik восходят к русскому «суслик». Это представитель семейства беличьих, часто живущий в норах на открытой местности.","На фотографии В виден небольшой суслик с плотным телом и коротким ухом. Сурок на фотографии Г крупнее."],"optionFigures":[{"src":"assets/chip/2020/7-8-12-1.webp","alt":"Крупный бурый грызун с маленькими ушами держит в передних лапах ветку.","width":384,"height":319,"detailSrc":"assets/chip/2020/detail/7-8-12-1.webp","pixelWidth":1024,"pixelHeight":851},{"src":"assets/chip/2020/7-8-12-2.webp","alt":"Небольшой грызун с несколькими продольными полосами на спине.","width":360,"height":384,"detailSrc":"assets/chip/2020/detail/7-8-12-2.webp","pixelWidth":1309,"pixelHeight":1397},{"src":"assets/chip/2020/7-8-12-3.webp","alt":"Серо-бежевый грызун с короткими округлыми ушами и светлым горлом.","width":288,"height":384,"detailSrc":"assets/chip/2020/detail/7-8-12-3.webp","pixelWidth":768,"pixelHeight":1024},{"src":"assets/chip/2020/7-8-12-4.webp","alt":"Крупный бурый грызун с невысокими ушами и крепкими передними лапами.","width":384,"height":184,"detailSrc":"assets/chip/2020/detail/7-8-12-4.webp","pixelWidth":960,"pixelHeight":459},{"src":"assets/chip/2020/7-8-12-5.webp","alt":"Коренастый грызун с чёрной грудью и светло-жёлтыми отметинами у щёк.","width":384,"height":288,"detailSrc":"assets/chip/2020/detail/7-8-12-5.webp","pixelWidth":1024,"pixelHeight":768}]},{"title":"Дольше всего без солнца","question":"В каком из перечисленных населённых пунктов полярная ночь длится дольше всего?","choices":["Мурманск","Норильск","Салехард","Воркута","посёлок Тикси"],"answer":4,"points":4,"steps":["Полярная ночь длится дольше ближе к Северному полюсу. Сравнивать нужно широты пунктов.","Тикси находится примерно на 71,6° северной широты. Остальные пункты из списка расположены южнее."],"adaptation":"Сравнение ограничено предложенным списком, так как в России есть точки значительно севернее."},{"title":"Путь у края материка","question":"Маршрут изображён на карте. Какая экспедиция в XVII веке обогнула Чукотку, вышла из Северного Ледовитого океана в Тихий и достигла бассейна Анадыря?","choices":["Ермака Тимофеевича","Семёна Дежнёва","Витуса Беринга","Фердинанда Врангеля","Ерофея Хабарова"],"answer":1,"points":4,"steps":["Экспедиция вышла с Колымы в 1648 году, прошла вдоль северного побережья и обогнула восточную оконечность материка.","Позднее участники достигли Анадыря. Такой путь связан с именем Семёна Дежнёва."],"figure":{"src":"assets/chip/2020/7-8-14.svg","alt":"Карта Чукотки, нижней Колымы и Анадыря. Красная линия проходит вдоль побережья и огибает восточную оконечность материка.","width":605,"height":350,"detailSrc":"assets/chip/2020/7-8-14.svg"}},{"title":"Впадина ниже уровня океана","question":"Какая из перечисленных впадин Евразии опускается ниже всего относительно уровня Мирового океана?","choices":["Турфанская","Карагие","Мёртвого моря","Акчакая","Кара-Богаз-Гол"],"answer":2,"points":4,"steps":["Берега Мёртвого моря находятся более чем на 400 метров ниже уровня Мирового океана.","Остальные впадины из списка тоже лежат ниже уровня моря, но их отрицательные отметки меньше по модулю."]},{"title":"География названий элементов","question":"Название какого химического элемента не связано со Скандинавией?","choices":["иттрий","эрбий","гафний","лютеций","гольмий"],"answer":3,"points":4,"steps":["Иттрий и эрбий связаны со шведским Иттербю. Гольмий назвали по латинскому имени Стокгольма, а гафний — Копенгагена.","Лютеций назвали в честь Лютеции, древнего имени Парижа. Это Франция."]},{"title":"Крупнейший дикий псовый","question":"На какой фотографии виден самый крупный современный дикий вид семейства псовых?","choices":["","","","",""],"answer":4,"points":4,"steps":["Серый волк крупнее большинства других диких псовых. У него длинные ноги, мощная морда и стоячие уши.","На снимке Д серый волк. Другие снимки показывают более мелких псовых."],"adaptation":"Уточнено, что сравниваются дикие виды.","optionFigures":[{"src":"assets/chip/2020/7-8-17-1.webp","alt":"Небольшой северный зверь со светлой шерстью.","width":384,"height":384,"detailSrc":"assets/chip/2020/detail/7-8-17-1.webp","pixelWidth":1280,"pixelHeight":1280},{"src":"assets/chip/2020/7-8-17-2.webp","alt":"Стройный серовато-рыжий зверь с острыми ушами и узкой мордой.","width":331,"height":384,"detailSrc":"assets/chip/2020/detail/7-8-17-2.webp","pixelWidth":565,"pixelHeight":656},{"src":"assets/chip/2020/7-8-17-3.webp","alt":"Стройный зверь с крупными округлыми ушами и пятнистой шерстью.","width":384,"height":216,"detailSrc":"assets/chip/2020/detail/7-8-17-3.webp","pixelWidth":500,"pixelHeight":281},{"src":"assets/chip/2020/7-8-17-4.webp","alt":"Коренастое длинношёрстное животное с тёмной маской на лице.","width":263,"height":384,"detailSrc":"assets/chip/2020/detail/7-8-17-4.webp","pixelWidth":1095,"pixelHeight":1600},{"src":"assets/chip/2020/7-8-17-5.webp","alt":"Серый длинноногий зверь с широкой мордой.","width":384,"height":297,"detailSrc":"assets/chip/2020/detail/7-8-17-5.webp","pixelWidth":1280,"pixelHeight":991}]},{"title":"Страна к западу от Гринвича","question":"Какая из этих стран расположена к западу от нулевого меридиана всей своей основной территорией и островами?","choices":["Дания","Португалия","Нидерланды","Франция","Испания"],"answer":1,"points":4,"steps":["Нулевой меридиан проходит через Францию и Испанию. Дания и Нидерланды в Европе лежат к востоку от него.","Португалия на Пиренейском полуострове и её островные области лежат западнее нулевого меридиана."]},{"title":"Море в устье Печоры","question":"В какое море впадает Печора?","choices":["Баренцева","Карского","моря Лаптевых","Восточно-Сибирского","моря Бофорта"],"answer":0,"points":4,"steps":["Печора течёт на север европейской части России. В устье она выходит в Печорскую губу.","Этот участок акватории относится к Баренцеву морю."]},{"title":"Глубокий синий камень","question":"Какой декоративный минерал с насыщенной синей окраской показан на фотографии?","choices":["рубин","яшма","лазурит","малахит","чароит"],"answer":2,"points":4,"steps":["У лазурита бывает глубокий цвет ультрамарина. Иногда в нём видны золотистые включения пирита.","Синий образец на снимке подходит под это описание. Малахит обычно зелёный, а рубин обычно красный."],"figure":{"src":"assets/chip/2020/7-8-20.webp","alt":"Неровный синий камень с мелкими золотистыми включениями.","width":384,"height":329,"detailSrc":"assets/chip/2020/detail/7-8-20.webp","pixelWidth":500,"pixelHeight":429}},{"title":"Шарики на листьях дуба","question":"Чем обычно являются небольшие шарики, образующиеся прямо на листьях дуба?","choices":["орешками","ядовитой защитой листа","молодыми желудями","галлами, связанными с личинками насекомых","частями для вегетативного размножения"],"answer":3,"points":5,"steps":["Некоторые орехотворки откладывают яйца в ткани растений. Рядом с личинкой растёт нарост из клеток самого растения.","Этот нарост называют галлом. Он защищает личинку и снабжает её пищей."],"figure":{"src":"assets/chip/2020/7-8-21.webp","alt":"На зелёном лопастном листе несколько круглых светло-зелёных наростов.","width":288,"height":384,"detailSrc":"assets/chip/2020/detail/7-8-21.webp","pixelWidth":769,"pixelHeight":1024}},{"title":"Граница через улицу","question":"Что обозначают белые знаки на мостовой у столиков в Барле?","choices":["границу пешеходной зоны","границу велосипедной дорожки","границу Бельгии и Нидерландов","линию между двумя кафе","границу Европы и Азии"],"answer":2,"points":5,"steps":["В Барле участки Бельгии и Нидерландов образуют мозаику. Граница может проходить через тротуары и здания.","Буквы B и NL обозначают две страны. Белые отметки показывают, где проходит государственная граница."],"figure":{"src":"assets/chip/2020/7-8-22.webp","alt":"Возле столиков на мостовой видны белые кресты и буквы NL и B.","width":384,"height":260,"detailSrc":"assets/chip/2020/detail/7-8-22.webp","pixelWidth":1143,"pixelHeight":774}},{"title":"Острова двух государств","question":"Между какими из перечисленных островов проходит государственная граница России и США?","choices":["Курильскими","Диомида","Командорскими","Медвежьими","Андреяновскими"],"answer":1,"points":5,"steps":["В Беринговом проливе два острова Диомида лежат близко друг к другу. Западный, остров Ратманова, принадлежит России.","Восточный, Малый Диомид, принадлежит США. Граница идёт по проливу между ними."]},{"title":"Листья и замёрзшая почва","question":"У дриады, или куропаточьей травы, на нижней стороне листьев густые волоски. От какого типа нехватки воды они помогают защититься, когда почва влажная, но её вода замёрзла?","choices":["от избытка ультрафиолетового излучения","от физической сухости","от физиологической сухости","от поедания северными оленями","от укусов насекомых"],"answer":2,"points":5,"steps":["В промёрзшей почве вода есть, но корни не могут легко её поглощать. Это называют физиологической сухостью.","Опушение снижает движение воздуха у поверхности листа и тем самым помогает уменьшить потерю воды."],"adaptation":"Добавлено состояние грунта, чтобы отличить физиологическую сухость от фактической нехватки воды в среде.","figure":{"src":"assets/chip/2020/7-8-24.webp","alt":"Белые раскрытые цветки с жёлтой серединой среди мелких кожистых листьев.","width":288,"height":384,"detailSrc":"assets/chip/2020/detail/7-8-24.webp","pixelWidth":1200,"pixelHeight":1600}},{"title":"Кавказская вершина на гербе","question":"На гербе какого города изображён Казбек, одна из высоких вершин Кавказа?","choices":["Пятигорска","Нальчика","Ставрополя","Тбилиси","Владикавказа"],"answer":4,"points":5,"steps":["Владикавказ лежит у северных предгорий Кавказа. На его гербе показан горный пейзаж.","Казбек — центральная снежная вершина на гербе Владикавказа."],"figure":{"src":"assets/chip/2020/7-8-25.svg","alt":"Герб с зелёными и красными полями, наверху снежные горные вершины.","width":270,"height":295,"detailSrc":"assets/chip/2020/7-8-25.svg","pixelWidth":"Щ","pixelHeight":"и"}},{"title":"Горный пояс Евразии","question":"Какая горная система не входит в Альпийско-Гималайский горный пояс?","choices":["Пиренеи","Карпаты","Альпы","Урал","Кавказ"],"answer":3,"points":5,"steps":["Альпы, Пиренеи, Карпаты и Кавказ относятся к южному поясу горообразования Евразии.","Уральские горы расположены севернее и имеют другую геологическую историю."]},{"title":"Свет в буковом лесу","question":"Что чаще всего ограничивает рост светолюбивых трав под сомкнутыми кронами в буковом лесу?","choices":["выделения из корней","срастание корней буков","малое число насекомых-опылителей","отсутствие переносчиков семян","затенение густыми кронами"],"answer":4,"points":5,"steps":["Густой полог перехватывает значительную часть света ещё над землёй.","Светолюбивые травы хуже растут в тени. Теневыносливые виды могут сохраняться и под буками."],"adaptation":"Речь о светолюбивых травах. Другие травы иногда встречаются и в густом буковом лесу."},{"title":"Рыба с лопастями плавников","question":"На индонезийской марке изображена одна из двух известных современных рыб какой группы?","choices":["акулы","скаты","целакантообразные","осетрообразные","сомообразные"],"answer":2,"points":5,"steps":["У рыбы на марке толстые основания парных плавников. Это признаки латимерии.","Группа целакантообразных известна по многочисленным окаменелостям. К ныне живущим её представителям относятся два вида латимерий."],"figure":{"src":"assets/chip/2020/7-8-28.webp","alt":"Почтовый блок Индонезии с изображением рыбы с широкими мясистыми плавниками.","width":480,"height":326,"detailSrc":"assets/chip/2020/detail/7-8-28.webp","pixelWidth":622,"pixelHeight":422}},{"title":"Возвращение лесного великана","question":"Какие животные исчезли из дикой природы в начале XX века, были восстановлены из животных в неволе и живут в Беловежской пуще?","choices":["","","","",""],"answer":0,"points":5,"steps":["К концу 1920-х годов диких зубров не осталось. Восстановить их популяции удалось благодаря животным, сохранившимся в неволе.","На снимке А европейский зубр. Его можно узнать по массивной передней части тела и коротким рогам."],"optionFigures":[{"src":"assets/chip/2020/7-8-29-1.webp","alt":"Высокий бурый зверь с мощной передней частью тела и короткими рогами.","width":384,"height":256,"detailSrc":"assets/chip/2020/detail/7-8-29-1.webp","pixelWidth":1280,"pixelHeight":853},{"src":"assets/chip/2020/7-8-29-2.webp","alt":"Крупный тёмный зверь с очень широкой головой и густой шерстью на плечах.","width":384,"height":251,"detailSrc":"assets/chip/2020/detail/7-8-29-2.webp","pixelWidth":1280,"pixelHeight":835},{"src":"assets/chip/2020/7-8-29-3.webp","alt":"Бурое домашнее копытное с длинной головой и рогами.","width":384,"height":256,"detailSrc":"assets/chip/2020/detail/7-8-29-3.webp","pixelWidth":1024,"pixelHeight":683},{"src":"assets/chip/2020/7-8-29-4.webp","alt":"Плотно сложенный зверь с длинной густой шерстью, рога загнуты книзу.","width":384,"height":256,"detailSrc":"assets/chip/2020/detail/7-8-29-4.webp","pixelWidth":500,"pixelHeight":333},{"src":"assets/chip/2020/7-8-29-5.webp","alt":"Тёмное копытное с толстыми рогами, основания которых образуют широкую поперечную пластину.","width":384,"height":256,"detailSrc":"assets/chip/2020/detail/7-8-29-5.webp","pixelWidth":1280,"pixelHeight":853}]},{"title":"Пейзаж у Волошина","question":"В стихотворении Максимилиана Волошина упоминаются солёный ветер, горечь трав и овечий колодец. Какому открытому сухому ландшафту соответствует такое описание?","choices":["степи","тундре","тайге","широколиственному лесу","жестколистному лесу"],"answer":0,"points":5,"steps":["В отрывке заметны травы и признаки засушливой местности. Такие черты характерны для степной природы юга.","Поэт часто писал о пейзажах Крыма. Из перечисленных вариантов открытому травянистому и сухому месту соответствует степь."]}]);
